		/// </summary>
		/// <returns>A new object that is a copy of this instance.</returns>
		public object Clone(IDictionary existingCopies)
		{
			if (existingCopies == null)
				existingCopies = new Hashtable();
				
			NotaEntityData _tmp = new NotaEntityData();
						
			_tmp.NotaId = this.NotaId;
			_tmp.OriginalNotaId = this.OriginalNotaId;
			
			_tmp.PorcentajeRetencion = this.PorcentajeRetencion;
			_tmp.MontoRetencion = this.MontoRetencion;
			_tmp.Fecha = this.Fecha;
			_tmp.Dias = this.Dias;
			_tmp.ClienteId = this.ClienteId;
			_tmp.VendedorId = this.VendedorId;
			_tmp.NroNota = this.NroNota;
			_tmp.MontoNota = this.MontoNota;
			
			#region Source Parent Composite Entities
			if (this.ClienteIdSource != null && existingCopies.Contains(this.ClienteIdSource))
				_tmp.ClienteIdSource = existingCopies[this.ClienteIdSource] as Cliente;
			else
				_tmp.ClienteIdSource = MakeCopyOf(this.ClienteIdSource, existingCopies) as Cliente;
			if (this.VendedorIdSource != null && existingCopies.Contains(this.VendedorIdSource))
				_tmp.VendedorIdSource = existingCopies[this.VendedorIdSource] as Vendedor;
			else
				_tmp.VendedorIdSource = MakeCopyOf(this.VendedorIdSource, existingCopies) as Vendedor;
			#endregion
		
			#region Child Collections
			//deep copy nested objects
			_tmp.MovimientoCuentaCollection = (TList<MovimientoCuenta>) MakeCopyOf(this.MovimientoCuentaCollection, existingCopies); 
			#endregion Child Collections
			
			//EntityState
			_tmp.EntityState = this.EntityState;
			
			return _tmp;
		}
		
		#endregion Clone Method
		
		/// <summary>
		///		Indicates state of object
		/// </summary>
